<!doctype html><html lang=en><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>make.fun · board</title>
<style>
body{margin:0;height:100vh;display:grid;grid-template:46px 1fr/318px 1fr;overflow:hidden;background:#0a0c10;color:#e9eef4;font:14px/1.5 system-ui,sans-serif}
a{color:inherit;text-decoration:none}[hidden]{display:none!important}
header{grid-column:1/3;display:flex;justify-content:space-between;align-items:center;padding:0 12px;border-bottom:1px solid #20272f}
#m{display:flex;gap:10px;font:10px monospace;color:#98a2af}
#l{overflow-y:auto;overflow-x:hidden;border-right:1px solid #20272f}
#f{display:block;width:calc(100% - 16px);margin:8px;padding:6px 7px;background:#05070a;border:1px solid #20272f;color:inherit}
#r a{display:block;padding:9px 12px;border-bottom:1px solid #12171d}
#r a:hover,#r a.o{background:#11161c}
#r a>b{display:block;color:#e9eef4;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-right:58px}
#r i{float:right;font:11px monospace;color:#98a2af;font-style:normal}
#r small{display:block;font:10px monospace;color:#98a2af;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#v>a,p{font:11px/1.7 monospace;color:#98a2af}
#r small b{margin-right:4px}
b,p b{color:#c9ff45}
#v{overflow-y:auto;padding:16px 22px 40px}
#l,#v{scrollbar-width:thin;scrollbar-color:#2a333d #0a0c10}
h1{font-size:19px;margin:6px 0}
p{margin:0 0 8px}
.bt{display:inline-block;margin:2px 0 10px;padding:6px 10px;background:#c9ff45;color:#000;font:700 12px system-ui}
.vh,.vr{display:grid;grid-template-columns:46px 1fr 110px 86px;align-items:center;padding:0 26px;font:11px monospace}
.vh{height:24px;font-size:9px;text-transform:uppercase;color:#98a2af;border-bottom:1px solid #20272f}
.vh span:nth-child(n+3),.vr span:nth-child(n+3){text-align:right}
.vs{height:calc(100vh - 158px);overflow:auto;max-width:820px}
.vr{height:34px;border-bottom:1px solid #141a21}
@media(max-width:700px){body{grid-template:46px 1fr/1fr}body.det #l{display:none}body:not(.det) #v{display:none}}
</style>
</head><body>
<header><a href="#/">make<i>.</i>fun</a><div id=m><span>req <b id=q1>0</b></span><span>304 <b id=q2>0</b></span><span>cache <b id=q3>0</b></span></div></header>
<aside id=l><input id=f placeholder="Filter title or slug"><div id=r></div></aside>
<section id=v></section>
<script>
const A='https://make.fun/api',M=new Map(),S={q:0,a:0,c:0},D=document,$=s=>D.querySelector(s),en=encodeURIComponent;
const h=s=>(s==null?'':''+s).replace(/</g,'&lt;');
const cd=d=>{const s=(Date.parse(d)-Date.now())/1e3|0,p=n=>('0'+n).slice(-2);return s<1?'closed':(s>86400?(s/86400|0)+'d ':'')+p(s%86400/3600|0)+':'+p(s%3600/60|0)+':'+p(s%60)};
const N0=20;
let B=[],cur='',R=new Map(),K=[],CD=[];
const cnt=()=>{$('#q1').textContent=S.q;$('#q2').textContent=S.a;$('#q3').textContent=S.c};

async function get(p){
const u=A+p,c=M.get(u),n=Date.now();
if(c&&n-c.t<8e3){S.c++;cnt();return c.b}
const k={Accept:'application/json'};
if(c&&c.e)k['If-None-Match']=c.e;
if(c&&c.l)k['If-Modified-Since']=c.l;
S.q++;cnt();
const r=await fetch(u,{headers:k});
if(r.status==304&&c){S.a++;c.t=n;cnt();return c.b}
if(!r.ok)throw Error(r.status);
const b=await r.json();
M.set(u,{e:r.headers.get('ETag'),l:r.headers.get('Last-Modified'),b,t:n});
return b
}

function paint(){
const H=$('#r'),f=$('#f').value.trim().toLowerCase(),n=Date.now();
K=[];
for(const i of B){
let r=R.get(i.slug);
if(!r){
const a=D.createElement('a');
a.href='#/bounty/'+i.slug;
a.innerHTML='<i></i><b></b><small><b></b><span></span></small>';
R.set(i.slug,r={a,n:a.children[1],t:a.children[0],s:a.children[2].children})
}
r.a.dataset.l=Date.parse(i.deadline)>n?1:0;
r.n.textContent=i.title||i.slug;
r.t.textContent=cd(i.deadline);
r.s[0].textContent='$'+i.rewardAmount;
r.s[1].textContent='pot $'+(+(i.potUsd??i.rewardAmount))+(i.entryFeeUsd?' · fee $'+i.entryFeeUsd:' · free')+' · '+(i.submissionCount||0)+' in';
r.d=i.deadline;H.append(r.a);K.push(r);
r.a.hidden=!!f&&!(i.slug+' '+i.title).toLowerCase().includes(f)
}
}

function vlist(d){
const a=d.entries||[],N=20,H=34;
const b=D.createElement('div');
b.innerHTML='<div class=vh><span>#</span><span>handle</span><span>win rate</span><span>size</span></div><div class=vs><i></i>'+'<div class=vr><span></span><a></a><span></span><span></span></div>'.repeat(N)+'<i></i></div>';
const sc=b.lastChild,RS=[...sc.querySelectorAll('.vr')];
const draw=()=>{
const t=Math.min(a.length-N,Math.max(0,sc.scrollTop/H|0));
sc.firstChild.style.height=t*H+'px';
sc.lastChild.style.height=Math.max(0,a.length-N-t)*H+'px';
RS.forEach((r,i)=>{const v=a[t+i],c=r.children,q=v.display||{};
r.hidden=!v;
if(!v)return;
c[0].textContent=v.rank||t+i+1;
c[1].textContent=v.handle;c[1].href='#/u/'+en(v.handle||'');
c[2].textContent=v.values.judge!=null?(v.values.judge/1e4).toFixed(1)+'%':(q[Object.keys(q)[0]]||'—');
c[3].textContent=v.values.bytes!=null?(v.values.bytes>>10)+' KB':(q.size||'—')
})};
sc.onscroll=draw;draw();
return b
}

async function draw(){
const p=location.hash.replace(/^#\/?/,'').split('/'),a=p[0],b=decodeURIComponent(p[1]||'');
cur=!a?'board':a==='bounty'&&b?(p[2]==='leaderboard'?'lb':'bn'):a==='u'&&b?'pf':'404';
D.body.classList.toggle('det',cur!=='board');
for(const[k,r]of R)r.a.classList.toggle('o',k===b);
window.__shotReady=false;
let t='Not found',s='no route at '+h(location.hash||'#/')+' · try #/ or #/u/&lt;handle&gt;',f='',x='',v,dl,bh;
try{
if(cur==='board'){
t='Bounty board';s=B.length+' bounties · '+B.filter(i=>Date.parse(i.deadline)>Date.now()).length+' open · pick one on the left';
const sum=k=>B.reduce((q,i)=>q+(+i[k]||0),0);f='pot <b>$'+sum('potUsd').toLocaleString()+'</b> · entries <b>'+sum('submissionCount').toLocaleString()+'</b>'
}else if(cur==='bn'){
const d=await get('/competitions/'+en(b));
t=h(d.title||b);s=h('ends '+String(d.deadline||'').slice(0,10)+(Date.parse(d.deadline)>Date.now()?' · open':' · closed'));
f='reward <b>$'+d.rewardAmount+'</b> · pot <b>$'+d.potUsd+'</b> · fee <b>'+(d.entryFeeUsd?'$'+d.entryFeeUsd:'free')+'</b> · entries <b>'+d.submissionCount+'</b> · ends in <b id=cd>'+cd(d.deadline)+'</b>';
x='<a class=bt href="#/bounty/'+en(b)+'/leaderboard">Leaderboard →</a><p>'+h(d.summary)+'</p>';dl=d.deadline
}else if(cur==='lb'){
const d=await get('/competitions/'+en(b)+'/leaderboard'),a0=d.entries||[];
t='Leaderboard';s=h((d.competition||{}).title||b)+' · '+(d.entries||[]).length+' entries · '+(d.phase||{}).title+' · '+N0+' rows mounted';bh='#/bounty/'+en(b);v=vlist(d);x='<div id=t></div><p>'+a0.length+' entries · '+N0+' rows in the DOM · scroll to move the window</p>'
}else if(cur==='pf'){
const d=await get('/profiles/'+en(b)).catch(()=>({})),c=d.record||{},e=d.solutions||[];
t=h(d.handle||b);s=h(d.bio||'public make.fun profile');
f='bounties <b>'+(c.competitions_entered??'—')+'</b> · wins <b>'+(c.competitions_won??'—')+'</b>';
x='<p>'+e.slice(0,6).map(y=>'<a href="#/bounty/'+en((y.competition||{}).slug||'')+'">'+h((y.competition||{}).title)+'</a>').join('<br>')+'</p>'
}
}catch(err){t='Could not load';s=h(err.message||'request failed')}
const cv=$('#v');
cv.innerHTML='<a href="'+(bh||'#/')+'">'+(bh?'← bounty':'← all bounties')+'</a><h1>'+t+'</h1><p>'+s+'</p>'+(f?'<p>'+f+'</p>':'')+x;
cv.scrollTop=0;
if(v)$('#t').append(v);
if(dl)CD=[$('#cd'),dl];
window.__shotReady=true
}

async function load(){
try{
const j=await get('/competitions');
const n=Date.now();
B=(j.items||[]).filter(x=>x&&x.slug).sort((x,y)=>(Date.parse(y.deadline)>n)-(Date.parse(x.deadline)>n)||Date.parse(x.deadline)-Date.parse(y.deadline));
paint();
if(cur==='board')draw()
}catch(x){$('#f').placeholder='board failed: '+x.message}
}

$('#f').oninput=paint;
onhashchange=draw;
setInterval(()=>{for(const r of K)r.t.textContent=cd(r.d);if(CD[0])CD[0].textContent=cd(CD[1])},1e3);
setInterval(load,45e3);
cnt();draw();load();
</script>
</body></html>
```
